sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {
    var method = request.httpMethod;
    try {
        if (method !== 'GET') {
            response.setStatus(405);
            return { success: false, error: 'Method not allowed' };
        }
        var body = request.pathParams.sys_id ?
            getOne(request.pathParams.sys_id) :
            getList(request.queryParams);
        response.setStatus(body.success ? 200 : 400);
        return body;
    } catch (e) {
        response.setStatus(500);
        return { success: false, error: e.message };
    }

    function getOne(sysId) {
        var gr = new GlideRecord('x_2145749_qc_dark_store');
        if (!gr.get(sysId)) {
            return { success: false, error: 'Store not found' };
        }
        var obj = toObj(gr);
        obj.latest_pulse_score = getLatestScore(sysId);
        return { success: true, result: obj };
    }

    function getList(qp) {
        var gr = new GlideRecord('x_2145749_qc_dark_store');
        if (qp.zone) gr.addQuery('zone', qp.zone);
        gr.orderBy('store_name');
        var limit = parseInt(qp.limit, 10) || 50;
        var offset = parseInt(qp.offset, 10) || 0;
        gr.chooseWindow(offset, offset + limit);
        gr.query();
        var results = [];
        while (gr.next()) {
            var obj = toObj(gr);
            obj.latest_pulse_score = getLatestScore(gr.getUniqueValue());
            results.push(obj);
        }
        return { success: true, result: results };
    }

    function getLatestScore(storeId) {
        var ps = new GlideRecord('x_2145749_qc_pulse_score');
        ps.addQuery('dark_store', storeId);
        ps.orderByDesc('snapshot_time');
        ps.setLimit(1);
        ps.query();
        if (ps.next()) {
            return {
                score: ps.score.toString(),
                band: ps.band.toString(),
                as_of: ps.snapshot_time.toString()
            };
        }
        return null;
    }

    function toObj(gr) {
        return {
            sys_id: gr.getUniqueValue(),
            name: gr.store_name.toString(),
            address: gr.address ? gr.address.toString() : '',
            zone: gr.zone.getDisplayValue(),
            status: gr.status.toString(),
            pulse_score: gr.pulse_score.toString(),
            pulse_score_band: gr.pulse_score_band.toString()
        };
    }
})(request, response);
